  "module.exports = " + JSON.stringify(BANK) + ";\n";
var OUTF = (CODE === "en" ? "eng" : CODE) + "_bank.js"; /* en → eng_bank.js (server-नाम यथावत) */
fs.writeFileSync("functions/" + OUTF, out);
